INSERT IGNORE INTO agent_ui_event (
    user_id, session_id, trace_id, event_seq, event_json, occurred_at, created_at
) VALUES (
    #{userId}, #{sessionId}, #{traceId}, #{eventSeq}, #{eventJson}, #{occurredAt}, NOW(3)
