mapper.select:
SELECT id
FROM agent_ui_event
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
  AND trace_id = #{traceId}
  AND event_seq = #{eventSeq}
LIMIT 1

SELECT id, user_id, session_id, trace_id, event_seq, event_json, occurred_at, created_at
FROM agent_ui_event
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
  AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}

SELECT id, user_id, session_id, trace_id, event_seq, event_json, occurred_at, created_at
FROM agent_ui_event
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
ORDER BY id DESC
LIMIT #{limit}
